// Compile-time embedded frontend assets, served over the custom protocol.
//
// Deliberately not `rust-embed`: that pulls a proc-macro crate plus `walkdir`,
// `sha2`, and friends to do what `include_bytes!` already does. The builder is
// generated by the CLI's build step, which already knows the asset list.

use std::borrow::Cow;

/// A generated table of `(absolute-path-in-built-output, bytes)`.
///
/// The CLI writes this file; `include!` -ing it means the payload lands in the
/// binary at compile time with no runtime filesystem access.
pub type AssetTable = &'static [(&'static str, &'static [u8])];

/// Look up a URL path in the asset table.
///
/// Returns `None` when nothing matches. Directory-ish paths fall back to
/// `index.html` so the root URL works.
pub fn lookup<'a>(assets: AssetTable, path: &str) -> Option<(&'a str, Cow<'a, [u8]>)> {
    let path = if path.is_empty() || path == "/" {
        "/index.html"
    } else {
        path
    };
    let path = path.trim_start_matches('/');

    assets
        .iter()
        .find(|(name, _)| *name == path)
        .map(|(name, bytes)| (*name, Cow::Borrowed(*bytes)))
}

/// Content type for a path, by extension.
///
/// A hand-written table instead of the `mime_guess` crate: a desktop app serves
/// maybe a dozen file types, and this keeps the dependency tree at wry+tao+serde_json.
pub fn content_type(path: &str) -> &'static str {
    let ext = path.rsplit('.').next().unwrap_or("");
    match ext {
        "html" | "htm" => "text/html; charset=utf-8",
        "js" | "mjs" => "text/javascript; charset=utf-8",
        "css" => "text/css; charset=utf-8",
        "json" => "application/json",
        "svg" => "image/svg+xml",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "webp" => "image/webp",
        "ico" => "image/x-icon",
        "woff" => "font/woff",
        "woff2" => "font/woff2",
        "ttf" => "font/ttf",
        "otf" => "font/otf",
        "wasm" => "application/wasm",
        "txt" => "text/plain; charset=utf-8",
        "map" => "application/json",
        _ => "application/octet-stream",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    static ASSETS: AssetTable = &[
        ("index.html", b"<html></html>"),
        ("assets/app.js", b"console.log(1)"),
    ];

    #[test]
    fn root_serves_index() {
        assert_eq!(lookup(ASSETS, "/").unwrap().0, "index.html");
        assert_eq!(lookup(ASSETS, "").unwrap().0, "index.html");
    }

    #[test]
    fn nested_paths_resolve() {
        assert_eq!(lookup(ASSETS, "/assets/app.js").unwrap().0, "assets/app.js");
    }

    #[test]
    fn traversal_does_not_escape_the_table() {
        assert!(lookup(ASSETS, "/../../etc/passwd").is_none());
        assert!(lookup(ASSETS, "/assets/../../../secret").is_none());
    }

    #[test]
    fn mime_table_covers_the_scaffold_types() {
        assert!(content_type("x.js").starts_with("text/javascript"));
        assert!(content_type("x.css").starts_with("text/css"));
        assert_eq!(content_type("x.unknown"), "application/octet-stream");
        assert_eq!(content_type("nested/dir/app.wasm"), "application/wasm");
    }
}
